"""D105: Global 3sigma recompute for 7 experiments.

Handles two data formats:
- 5method_leadlag.json (run_5method_analysis output)
- analysis_results.json (d102_rerun_8pair output)

Recomputes threshold_onset with true 3sigma, keeps other 4 methods unchanged,
recalculates K>=4 and K>=3.
"""

import json, os, sys
import numpy as np
from itertools import product
from datetime import datetime

CANARIES = ["token_entropy", "ece"]
DOWNSTREAMS = ["distinct_1", "distinct_2", "distinct_3", "mauve"]
LOWER_IS_WORSE = {"token_entropy", "effective_rank", "distinct_1", "distinct_2", "distinct_3", "mauve"}


def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()


def extract(metrics_list, name):
    return np.array([m[name] for m in sorted(metrics_list, key=lambda x: x["generation"])])


def onset_gen_3sigma(series, name):
    s = orient(series, name)
    base, sigma = s[0], np.std(s)
    if sigma < 1e-12:
        return None
    thresh = base + 3 * sigma
    for i in range(1, len(s)):
        if s[i] > thresh:
            return i
    return None


def threshold_lead_3sigma(c, d, cn, dn):
    co = onset_gen_3sigma(c, cn)
    do = onset_gen_3sigma(d, dn)
    if co is None or do is None:
        return {"canary_onset": co, "downstream_onset": do, "lead_time": None, "significant": False}
    lt = do - co
    return {"canary_onset": int(co), "downstream_onset": int(do), "lead_time": int(lt), "significant": bool(lt > 0)}


def onset_gen_2sigma(series, name):
    s = orient(series, name)
    base, sigma = s[0], np.std(s)
    if sigma < 1e-12:
        return None
    thresh = base + 2 * sigma
    for i in range(1, len(s)):
        if s[i] > thresh:
            return i
    return None


def assemble_metrics(exp_dir):
    all_path = os.path.join(exp_dir, "all_metrics.json")
    if os.path.exists(all_path):
        with open(all_path) as f:
            return json.load(f)
    metrics = []
    gen_idx = 0
    while True:
        mpath = os.path.join(exp_dir, f"gen_{gen_idx}", "metrics.json")
        if not os.path.exists(mpath):
            break
        with open(mpath) as f:
            m = json.load(f)
        m["generation"] = gen_idx
        metrics.append(m)
        gen_idx += 1
    return sorted(metrics, key=lambda x: x["generation"]) if metrics else None


def get_sig(method_result):
    """Best available significance: significant_fdr > sig_fdr_permethod > significant."""
    for key in ["significant_fdr", "sig_fdr_permethod"]:
        v = method_result.get(key)
        if v is not None:
            return bool(v)
    return bool(method_result.get("significant", False))


def extract_sigs_from_5method(json_path, cn, dn):
    """Extract per-pair method significance from 5method_leadlag.json format."""
    with open(json_path) as f:
        data = json.load(f)
    for pair in data["pairs"]:
        if pair["canary"] == cn and pair["downstream"] == dn:
            fwd = pair["forward"]
            return {
                "naive_xcorr": get_sig(fwd["naive_xcorr"]),
                "diff_xcorr": get_sig(fwd["diff_xcorr"]),
                "perm_granger": get_sig(fwd["perm_granger"]),
                "ty_granger": get_sig(fwd["ty_granger"]),
                "perm_granger_rev": get_sig(pair.get("reverse", {}).get("perm_granger", {})),
            }
    return None


def extract_sigs_from_analysis_results(json_path, cn, dn):
    """Extract per-pair method significance from analysis_results.json format."""
    with open(json_path) as f:
        data = json.load(f)
    for pd in data["pair_details"]:
        if pd["canary"] == cn and pd["downstream"] == dn:
            r = pd["results"]
            return {
                "naive_xcorr": get_sig(r.get("naive_xcorr", {})),
                "diff_xcorr": get_sig(r.get("diff_xcorr", {})),
                "perm_granger": get_sig(r.get("perm_granger_fwd", {})),
                "ty_granger": get_sig(r.get("ty_granger", {})),
                "perm_granger_rev": get_sig(r.get("perm_granger_rev", {})),
            }
    return None


# Experiment configs: exp_id -> (dir_path, json_format)
# json_format: "5method" or "analysis_results"
EXPERIMENTS = {}


def configure_experiments(base_dir):
    """Auto-detect available experiments and their data formats."""
    candidates = [
        # (registry_exp_id, results_subdir, display_name)
        ("scale_69b_a100_s42", "results/scale_check/pythia69b_wiki_a100_s42", "Pythia-6.9B Wiki s42"),
        ("qwen35_08b_wiki_a100_s42_v2", "results/generalize/qwen35_08b_wiki_a100_s42_fp32_v2", "Qwen3.5-0.8B Wiki s42"),
        ("padding_robustness_a100_s42_fp32", "results/padding_robustness/a100_s42_fp32", "Pythia-410M Wiki padding s42"),
        ("generalize_pythia410m_wiki_a100_s42", "results/generalize/pythia410m_wiki_a100_s42", "Pythia-410M Wiki s42"),
        ("gen_wiki_gpt2m_a100_s42_v4", "results/generalize/gpt2m_wiki_a100_s42", "GPT-2m Wiki s42"),
        ("gen_gpt2m_a100_s43_fp32", "results/gen_wiki_gpt2m_a100_s43", "GPT-2m Wiki s43"),
        ("generalize_opt1b_wiki_a100_s42", "results/generalize/opt1b_wiki_a100_s42", "OPT-1.3B Wiki s42"),
    ]
    found = {}
    for exp_id, subdir, display in candidates:
        full_dir = os.path.join(base_dir, subdir)
        if not os.path.isdir(full_dir):
            continue
        # Check for metrics data
        has_metrics = os.path.exists(os.path.join(full_dir, "all_metrics.json"))
        if not has_metrics:
            # Try assembling from gen_*/metrics.json
            if not os.path.exists(os.path.join(full_dir, "gen_0", "metrics.json")):
                continue
        # Determine analysis format
        five_method = os.path.join(full_dir, "analysis", "5method_leadlag.json")
        analysis_res = os.path.join(full_dir, "analysis_results.json")
        if os.path.exists(five_method):
            fmt = "5method"
            json_path = five_method
        elif os.path.exists(analysis_res):
            fmt = "analysis_results"
            json_path = analysis_res
        else:
            fmt = "none"
            json_path = None
        found[exp_id] = {
            "dir": full_dir,
            "format": fmt,
            "json_path": json_path,
            "display": display,
        }
    return found


def process_experiment(exp_id, exp_info):
    exp_dir = exp_info["dir"]
    fmt = exp_info["format"]
    json_path = exp_info["json_path"]

    metrics_list = assemble_metrics(exp_dir)
    if not metrics_list:
        return None
    n_gens = len(metrics_list)

    pair_results = {}
    for cn, dn in product(CANARIES, DOWNSTREAMS):
        pk = f"{cn}->{dn}"

        c = extract(metrics_list, cn)
        d = extract(metrics_list, dn)

        # 3sigma threshold
        thr_3s = threshold_lead_3sigma(c, d, cn, dn)
        # 2sigma for comparison
        co_2s = onset_gen_2sigma(c, cn)
        do_2s = onset_gen_2sigma(d, dn)
        thr_2s_sig = (co_2s is not None and do_2s is not None and (do_2s - co_2s) > 0)

        # Other methods from existing analysis
        if fmt == "5method" and json_path:
            sigs = extract_sigs_from_5method(json_path, cn, dn)
        elif fmt == "analysis_results" and json_path:
            sigs = extract_sigs_from_analysis_results(json_path, cn, dn)
        else:
            sigs = {"naive_xcorr": False, "diff_xcorr": False, "perm_granger": False, "ty_granger": False, "perm_granger_rev": False}

        if sigs is None:
            sigs = {"naive_xcorr": False, "diff_xcorr": False, "perm_granger": False, "ty_granger": False, "perm_granger_rev": False}

        votes_3s = {
            "naive_xcorr": sigs["naive_xcorr"],
            "diff_xcorr": sigs["diff_xcorr"],
            "threshold_3sigma": thr_3s["significant"],
            "perm_granger": sigs["perm_granger"],
            "ty_granger": sigs["ty_granger"],
        }
        k_3s = sum(votes_3s.values())

        votes_2s = {
            "naive_xcorr": sigs["naive_xcorr"],
            "diff_xcorr": sigs["diff_xcorr"],
            "threshold_2sigma": thr_2s_sig,
            "perm_granger": sigs["perm_granger"],
            "ty_granger": sigs["ty_granger"],
        }
        k_2s = sum(votes_2s.values())

        pair_results[pk] = {
            "k_3sigma": k_3s,
            "k_2sigma": k_2s,
            "votes_3s": votes_3s,
            "votes_2s": votes_2s,
            "thr_3s": thr_3s,
            "thr_2s_onset": (co_2s, do_2s),
            "perm_granger_rev": sigs.get("perm_granger_rev", False),
        }

    # Aggregate
    k4_3s = sum(1 for v in pair_results.values() if v["k_3sigma"] >= 4)
    k3_3s = sum(1 for v in pair_results.values() if v["k_3sigma"] >= 3)
    k4_2s = sum(1 for v in pair_results.values() if v["k_2sigma"] >= 4)
    k3_2s = sum(1 for v in pair_results.values() if v["k_2sigma"] >= 3)
    naive_ct = sum(1 for v in pair_results.values() if v["votes_3s"]["naive_xcorr"])
    diff_ct = sum(1 for v in pair_results.values() if v["votes_3s"]["diff_xcorr"])
    thr3_ct = sum(1 for v in pair_results.values() if v["votes_3s"]["threshold_3sigma"])
    pg_ct = sum(1 for v in pair_results.values() if v["votes_3s"]["perm_granger"])
    ty_ct = sum(1 for v in pair_results.values() if v["votes_3s"]["ty_granger"])
    pg_rev_ct = sum(1 for v in pair_results.values() if v["perm_granger_rev"])
    thr2_ct = sum(1 for v in pair_results.values() if v["votes_2s"]["threshold_2sigma"])

    return {
        "n_gens": n_gens,
        "display": exp_info["display"],
        "format": fmt,
        "k4_3sigma": k4_3s,
        "k3_3sigma": k3_3s,
        "k4_2sigma": k4_2s,
        "k3_2sigma": k3_2s,
        "naive": naive_ct,
        "diff_xcorr": diff_ct,
        "threshold_3sigma": thr3_ct,
        "threshold_2sigma": thr2_ct,
        "perm_granger_fwd": pg_ct,
        "perm_granger_rev": pg_rev_ct,
        "ty_granger": ty_ct,
        "pairs": pair_results,
    }


class NumpyEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (np.integer,)): return int(obj)
        if isinstance(obj, (np.floating,)): return float(obj)
        if isinstance(obj, np.ndarray): return obj.tolist()
        if isinstance(obj, (np.bool_,)): return bool(obj)
        return super().default(obj)


def main():
    base_dir = os.path.dirname(os.path.abspath(__file__))
    experiments = configure_experiments(base_dir)

    if not experiments:
        print("No experiments found on this server.")
        return

    print(f"Found {len(experiments)} experiments on this server:")
    for eid, info in experiments.items():
        print(f"  {eid}: {info['dir']} ({info['format']})")

    all_results = {}
    for exp_id, exp_info in experiments.items():
        result = process_experiment(exp_id, exp_info)
        if result is None:
            print(f"\nSKIPPED {exp_id}: no metrics data")
            continue
        all_results[exp_id] = result

        r = result
        print(f"\n{'='*90}")
        print(f"{exp_id} [{r['display']}] (T={r['n_gens']}, src={r['format']})")
        print(f"{'='*90}")
        print(f"  K>=4(3s)={r['k4_3sigma']}/8  K>=3(3s)={r['k3_3sigma']}/8  |  K>=4(2s)={r['k4_2sigma']}/8  K>=3(2s)={r['k3_2sigma']}/8")
        print(f"  Naive={r['naive']}/8  DiffX={r['diff_xcorr']}/8  Thr3s={r['threshold_3sigma']}/8  PermG={r['perm_granger_fwd']}/8(rev={r['perm_granger_rev']}/8)  TY={r['ty_granger']}/8")
        print(f"\n  {'Pair':<28} {'K3s':>4} {'Naive':>6} {'DiffX':>6} {'Thr3s':>6} {'PermG':>6} {'TY':>6} | 3s onset           2s onset")
        print(f"  {'-'*95}")
        s = lambda x: "Y" if x else "n"
        for pk in sorted(result["pairs"].keys()):
            pv = result["pairs"][pk]
            v = pv["votes_3s"]
            t3 = pv["thr_3s"]
            t2c, t2d = pv["thr_2s_onset"]
            t3c = t3["canary_onset"] if t3["canary_onset"] is not None else "-"
            t3d = t3["downstream_onset"] if t3["downstream_onset"] is not None else "-"
            t2cs = t2c if t2c is not None else "-"
            t2ds = t2d if t2d is not None else "-"
            print(f"  {pk:<28} {pv['k_3sigma']:>4} {s(v['naive_xcorr']):>6} {s(v['diff_xcorr']):>6} "
                  f"{s(v['threshold_3sigma']):>6} {s(v['perm_granger']):>6} {s(v['ty_granger']):>6} | "
                  f"c={t3c}->d={t3d}      c={t2cs}->d={t2ds}")

    # Summary table
    print(f"\n\n{'='*120}")
    print("D105 SUMMARY: 3sigma recompute (fdr_permethod)")
    print(f"{'='*120}")
    print(f"{'Experiment':<42} {'PermG_f':>7} {'PermG_r':>7} {'K>=4(3s)':>9} {'K>=3(3s)':>9} {'Thr(3s)':>8} {'Thr(2s)':>8} {'Change':>8}")
    print(f"{'-'*120}")
    for exp_id in ["scale_69b_a100_s42", "qwen35_08b_wiki_a100_s42_v2", "padding_robustness_a100_s42_fp32",
                    "generalize_pythia410m_wiki_a100_s42", "gen_wiki_gpt2m_a100_s42_v4",
                    "gen_gpt2m_a100_s43_fp32", "generalize_opt1b_wiki_a100_s42"]:
        if exp_id not in all_results:
            continue
        r = all_results[exp_id]
        delta = r['threshold_3sigma'] - r['threshold_2sigma']
        print(f"{exp_id:<42} {r['perm_granger_fwd']:>2}/8    {r['perm_granger_rev']:>2}/8    "
              f"{r['k4_3sigma']:>2}/8      {r['k3_3sigma']:>2}/8      "
              f"{r['threshold_3sigma']:>2}/8     {r['threshold_2sigma']:>2}/8     {delta:>+3}")

    # Save JSON
    save_dir = os.path.join(base_dir, "results", "analysis")
    os.makedirs(save_dir, exist_ok=True)
    save_path = os.path.join(save_dir, "3sigma_recompute_d105.json")

    save_data = {}
    for exp_id, r in all_results.items():
        save_data[exp_id] = {k: v for k, v in r.items() if k != "pairs"}
        save_data[exp_id]["per_pair"] = {}
        for pk, pv in r["pairs"].items():
            save_data[exp_id]["per_pair"][pk] = {
                "k_3sigma": pv["k_3sigma"],
                "k_2sigma": pv["k_2sigma"],
                "votes_3s": pv["votes_3s"],
                "threshold_3sigma_onset": pv["thr_3s"],
                "perm_granger_rev": pv["perm_granger_rev"],
            }

    with open(save_path, "w") as f:
        json.dump({
            "timestamp": datetime.now().isoformat(),
            "task": "D105",
            "config": {
                "canaries": CANARIES, "downstreams": DOWNSTREAMS,
                "n_pairs": 8, "threshold_sigma": 3,
                "sig_criterion": "fdr_permethod (significant_fdr where available, fallback to significant)",
                "note": "method_ablation._onset_gen used 2sigma, now fixed to 3sigma. This recompute uses true 3sigma.",
            },
            "results": save_data,
        }, f, indent=2, cls=NumpyEncoder)
    print(f"\nSaved: {save_path}")


if __name__ == "__main__":
    main()
